--
-- Name: anfrage_pruefen(); Type: FUNCTION; Schema: privat; Owner: -
--

CREATE FUNCTION privat.anfrage_pruefen() RETURNS void
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
begin
  if current_setting('request.method', true) not in ('GET', 'HEAD', 'OPTIONS')
     and current_setting('request.path', true) ~ '/(spatial_ref_sys|geometry_columns|geography_columns)' then
    raise exception 'Schreiben nicht erlaubt' using errcode = '42501';
  end if;
  -- PostGIS-Hilfsfunktionen (z. B. st_estimatedextent, security definer) nicht über die API aufrufbar
  if current_setting('request.path', true) ~* '/rpc/(_?st_|postgis|geometry|geography|box|addgeometry|dropgeometry|updategeometry|populate_geometry|find_srid|gettransactionid|lockrow|unlockrows|addauth|checkauth|disablelongtransactions|enablelongtransactions)' then
    raise exception 'Nicht erlaubt' using errcode = '42501';
  end if;
end $$;


--
-- Name: drosseln(text, integer, interval); Type: FUNCTION; Schema: privat; Owner: -
--

CREATE FUNCTION privat.drosseln(p_art text, p_max integer, p_fenster interval) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  kopf json := nullif(current_setting('request.headers', true), '')::json;
  ip text := coalesce(kopf->>'cf-connecting-ip', split_part(kopf->>'x-forwarded-for', ',', 1), kopf->>'x-real-ip');
  s text;
begin
  if ip is null or trim(ip) = '' then return; end if;
  -- Hash mit geheimem Salz und Datum: nicht auf die IP-Adresse zurückrechenbar und nur am selben Tag verknüpfbar
  s := encode(extensions.digest((select wert from privat.geheimnis limit 1) || convert_to(trim(ip) || current_date::text, 'UTF8'), 'sha256'), 'hex');
  if (select coalesce(sum(anzahl), 0) from privat.drossel d where d.art = p_art and d.schluessel = s and d.zeit > now() - p_fenster) >= p_max then
    raise exception 'Zu viele Anfragen, bitte später erneut versuchen' using errcode = 'P0001';
  end if;
  insert into privat.drossel as d (art, schluessel, zeit) values (p_art, s, date_trunc('minute', now()))
  on conflict (art, schluessel, zeit) do update set anzahl = d.anzahl + 1;
end $$;


--
-- Name: anzeigen_geom_setzen(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.anzeigen_geom_setzen() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
begin
  if new.koordinate_lat is not null and new.koordinate_lon is not null then
    new.geom := st_setsrid(st_point(new.koordinate_lon, new.koordinate_lat), 4326)::geography;
  end if;
  return new;
end $$;


--
-- Name: anzeigen_moderation_schuetzen(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.anzeigen_moderation_schuetzen() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if coalesce(current_setting('immobil.moderation', true), '') <> 'an' then
    if tg_op = 'INSERT' then
      new.sperr_kategorie := null; new.sperrgrund := null; new.gesperrt_am := null;
      new.einspruch := null; new.einspruch_am := null; new.einspruch_antwort := null; new.einspruch_entschieden_am := null;
    else
      new.sperr_kategorie := old.sperr_kategorie; new.sperrgrund := old.sperrgrund; new.gesperrt_am := old.gesperrt_am;
      new.einspruch := old.einspruch; new.einspruch_am := old.einspruch_am;
      new.einspruch_antwort := old.einspruch_antwort; new.einspruch_entschieden_am := old.einspruch_entschieden_am;
    end if;
  end if;
  return new;
end $$;


--
-- Name: anzeigen_naechste_haltestelle(integer[], integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.anzeigen_naechste_haltestelle(linien_ids integer[], radius_m integer) RETURNS TABLE(anzeige_id uuid, distanz_m integer, haltestelle text, linie text)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'extensions'
    AS $$
  select distinct on (a.id)
    a.id, round(st_distance(a.geom, h.geom))::integer, h.name, l.nummer
  from anzeigen a
  join oepnv_haltestellen h on st_dwithin(a.geom, h.geom, radius_m)
  join oepnv_linie_haltestelle lh on lh.stop_id = h.stop_id and lh.linie_id = any (linien_ids)
  join oepnv_linien l on l.linie_id = lh.linie_id
  order by a.id, st_distance(a.geom, h.geom);
$$;


