CASE
    WHEN ((koordinate_lat IS NOT NULL) AND (koordinate_lon IS NOT NULL)) THEN (public.st_setsrid(public.st_makepoint(koordinate_lon, koordinate_lat), 4326))::public.geography
    ELSE NULL::public.geography
