    CONSTRAINT anzeigen_anbieter_name_check CHECK ((char_length(anbieter_name) <= 200)),
    CONSTRAINT anzeigen_anbieter_typ_check CHECK ((anbieter_typ = ANY (ARRAY['privat'::text, 'gewerblich'::text]))),
    CONSTRAINT anzeigen_beschreibung_check CHECK ((char_length(beschreibung) <= 5000)),
    CONSTRAINT anzeigen_einspruch_antwort_check CHECK ((char_length(einspruch_antwort) <= 2000)),
    CONSTRAINT anzeigen_einspruch_check CHECK ((char_length(einspruch) <= 2000)),
    CONSTRAINT anzeigen_energieausweis_art_check CHECK ((energieausweis_art = ANY (ARRAY['verbrauch'::text, 'bedarf'::text, 'nicht_erforderlich'::text]))),
    CONSTRAINT anzeigen_energieeffizienzklasse_check CHECK (((energieeffizienzklasse IS NULL) OR (energieeffizienzklasse = ANY (ARRAY['A+'::text, 'A'::text, 'B'::text, 'C'::text, 'D'::text, 'E'::text, 'F'::text, 'G'::text, 'H'::text])))),
    CONSTRAINT anzeigen_energietraeger_check CHECK ((char_length(energietraeger) <= 100)),
    CONSTRAINT anzeigen_objektart_check CHECK (((objektart IS NULL) OR (objektart = ANY (ARRAY['etagenwohnung'::text, 'dachgeschoss'::text, 'maisonette'::text, 'penthouse'::text, 'erdgeschoss'::text, 'souterrain'::text, 'loft'::text, 'einfamilienhaus'::text, 'mehrfamilienhaus'::text, 'reihenhaus'::text, 'doppelhaushaelfte'::text, 'bungalow'::text, 'villa'::text])))),
    CONSTRAINT anzeigen_provision_check CHECK ((char_length(provision) <= 200)),
    CONSTRAINT anzeigen_sperr_kategorie_check CHECK ((sperr_kategorie = ANY (ARRAY['betrug'::text, 'falsche_angaben'::text, 'diskriminierung'::text, 'rechtswidrig'::text, 'regelverstoss'::text, 'sonstiges'::text]))),
    CONSTRAINT anzeigen_sperrgrund_check CHECK ((char_length(sperrgrund) <= 2000)),
