--
-- Name: anzeigen_nahe_linien(integer[], integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.anzeigen_nahe_linien(linien_ids integer[], radius_m integer) RETURNS SETOF public.anzeigen
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'extensions'
    AS $$
  select a.*
  from anzeigen a
  where a.id in (
    select a2.id
    from oepnv_linie_haltestelle lh
    join oepnv_haltestellen h on h.stop_id = lh.stop_id
    join anzeigen a2 on st_dwithin(a2.geom, h.geom, radius_m)
    where lh.linie_id = any (linien_ids)
  );
$$;


--
-- Name: einspruch_ablehnen(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.einspruch_ablehnen(p_id uuid, p_antwort text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if not public.ist_moderator() then raise exception 'Keine Berechtigung' using errcode = '42501'; end if;
  if char_length(trim(coalesce(p_antwort, ''))) < 10 then raise exception 'Bitte eine Begründung mit mindestens 10 Zeichen angeben'; end if;
  perform set_config('immobil.moderation', 'an', true);
  update public.anzeigen set einspruch_antwort = trim(p_antwort), einspruch_entschieden_am = now()
  where id = p_id and status = 'gesperrt' and einspruch is not null;
  if not found then raise exception 'Kein offener Einspruch'; end if;
end $$;


--
-- Name: einspruch_einlegen(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.einspruch_einlegen(p_id uuid, p_text text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if char_length(trim(coalesce(p_text, ''))) < 10 then raise exception 'Bitte begründe deinen Einspruch mit mindestens 10 Zeichen'; end if;
  perform set_config('immobil.moderation', 'an', true);
  update public.anzeigen set einspruch = trim(p_text), einspruch_am = now()
  where id = p_id and inserent_id = auth.uid() and status = 'gesperrt' and einspruch is null;
  if not found then raise exception 'Einspruch nicht möglich'; end if;
end $$;


--
-- Name: haltestellen_der_linien(integer[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.haltestellen_der_linien(linien_ids integer[]) RETURNS TABLE(stop_id text, name text, lat double precision, lon double precision)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'extensions'
    AS $$
  select distinct h.stop_id, h.name, st_y(h.geom::geometry), st_x(h.geom::geometry)
  from oepnv_linie_haltestelle lh
  join oepnv_haltestellen h on h.stop_id = lh.stop_id
  where lh.linie_id = any (linien_ids);
$$;


--
-- Name: inserat_drosseln(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.inserat_drosseln() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if (select count(*) from public.anzeigen where inserent_id = auth.uid() and erstellt_am > now() - interval '1 day') >= 10 then
    raise exception 'Zu viele neue Inserate heute, bitte morgen erneut versuchen' using errcode = 'P0001';
  end if;
  return new;
end $$;


--
-- Name: inserat_freigeben(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.inserat_freigeben(p_id uuid, p_antwort text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if not public.ist_moderator() then raise exception 'Keine Berechtigung' using errcode = '42501'; end if;
  perform set_config('immobil.moderation', 'an', true);
  update public.anzeigen set status = 'aktiv', sperr_kategorie = null, sperrgrund = null, gesperrt_am = null,
    einspruch = null, einspruch_am = null, einspruch_antwort = null, einspruch_entschieden_am = null
  where id = p_id and status = 'gesperrt';
  if not found then raise exception 'Inserat ist nicht gesperrt'; end if;
end $$;


--
-- Name: inserat_sperren(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.inserat_sperren(p_id uuid, p_kategorie text, p_grund text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if not public.ist_moderator() then raise exception 'Keine Berechtigung' using errcode = '42501'; end if;
  if char_length(trim(coalesce(p_grund, ''))) < 10 then raise exception 'Bitte eine Begründung mit mindestens 10 Zeichen angeben'; end if;
  perform set_config('immobil.moderation', 'an', true);
  update public.anzeigen set status = 'gesperrt', sperr_kategorie = p_kategorie, sperrgrund = trim(p_grund), gesperrt_am = now(),
    einspruch = null, einspruch_am = null, einspruch_antwort = null, einspruch_entschieden_am = null
  where id = p_id;
  if not found then raise exception 'Inserat nicht gefunden'; end if;
  update public.meldungen set erledigt = true where anzeige_id = p_id and not erledigt;
end $$;


--
-- Name: ist_moderator(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ist_moderator() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (select 1 from privat.moderatoren where nutzer_id = auth.uid());
$$;


--
-- Name: meldung_drosseln(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.meldung_drosseln() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  perform privat.drosseln('meldung', 5, interval '1 hour');
  return new;
end $$;


--
-- Name: meldung_erledigen(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.meldung_erledigen(p_id uuid, p_erledigt boolean DEFAULT true) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if not public.ist_moderator() then raise exception 'Keine Berechtigung' using errcode = '42501'; end if;
  update public.meldungen set erledigt = p_erledigt where id = p_id;
end $$;


--
-- Name: nachricht_drosseln(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.nachricht_drosseln() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  perform privat.drosseln('nachricht', 10, interval '1 hour');
  return new;
end $$;


--
-- Name: nachricht_vorbereiten(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.nachricht_vorbereiten() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare inserent uuid;
begin
  select inserent_id into inserent from anzeigen where id = new.anzeige_id and status = 'aktiv';
  if inserent is null then raise exception 'Dieses Inserat kann nicht kontaktiert werden'; end if;
  new.empfaenger_id := inserent;
  new.absender_id := auth.uid();
  new.gelesen := false;
  new.erstellt_am := now();
  if (select count(*) from nachrichten where lower(email) = lower(new.email) and erstellt_am > now() - interval '1 hour') >= 5 then
    raise exception 'Zu viele Nachrichten, bitte später erneut versuchen';
  end if;
  return new;
end $$;


