--
-- Name: anzeigen Aktive Inserate lesen; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "Aktive Inserate lesen" ON public.anzeigen FOR SELECT USING (((status = 'aktiv'::text) OR (inserent_id = ( SELECT auth.uid() AS uid))));


--
-- Name: anzeigen Eigene Inserate anlegen; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "Eigene Inserate anlegen" ON public.anzeigen FOR INSERT TO authenticated WITH CHECK (((inserent_id = ( SELECT auth.uid() AS uid)) AND (status = ANY (ARRAY['aktiv'::text, 'pausiert'::text]))));


--
-- Name: anzeigen Eigene Inserate löschen; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "Eigene Inserate löschen" ON public.anzeigen FOR DELETE TO authenticated USING ((inserent_id = ( SELECT auth.uid() AS uid)));


--
-- Name: anzeigen Eigene Inserate ändern; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "Eigene Inserate ändern" ON public.anzeigen FOR UPDATE TO authenticated USING (((inserent_id = ( SELECT auth.uid() AS uid)) AND (status <> 'gesperrt'::text))) WITH CHECK (((inserent_id = ( SELECT auth.uid() AS uid)) AND (status = ANY (ARRAY['aktiv'::text, 'pausiert'::text]))));


--
-- Name: nachrichten Eigene Nachrichten lesen; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "Eigene Nachrichten lesen" ON public.nachrichten FOR SELECT TO authenticated USING (((empfaenger_id = ( SELECT auth.uid() AS uid)) OR (absender_id = ( SELECT auth.uid() AS uid))));


--
-- Name: nachrichten Empfänger löscht; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "Empfänger löscht" ON public.nachrichten FOR DELETE TO authenticated USING ((empfaenger_id = ( SELECT auth.uid() AS uid)));


--
-- Name: nachrichten Empfänger markiert gelesen; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "Empfänger markiert gelesen" ON public.nachrichten FOR UPDATE TO authenticated USING ((empfaenger_id = ( SELECT auth.uid() AS uid))) WITH CHECK ((empfaenger_id = ( SELECT auth.uid() AS uid)));


--
-- Name: meldungen Jeder darf melden; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "Jeder darf melden" ON public.meldungen FOR INSERT TO authenticated, anon WITH CHECK (((erledigt = false) AND ((nutzer_id IS NULL) OR (nutzer_id = ( SELECT auth.uid() AS uid)))));


--
-- Name: anzeigen Moderatoren lesen Inserate; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "Moderatoren lesen Inserate" ON public.anzeigen FOR SELECT TO authenticated USING (( SELECT public.ist_moderator() AS ist_moderator));


--
-- Name: meldungen Moderatoren lesen Meldungen; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "Moderatoren lesen Meldungen" ON public.meldungen FOR SELECT TO authenticated USING (( SELECT public.ist_moderator() AS ist_moderator));


--
-- Name: nachrichten Nachricht senden; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "Nachricht senden" ON public.nachrichten FOR INSERT TO authenticated, anon WITH CHECK (true);


